const message = $('Zalo Bot Trigger').first()?.json?.message ?? {};
const chat = message.chat ?? {};

const pick = (value) => {
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  return text === '' ? null : text;
};

const chatId = pick(chat.id ?? message.chatId ?? message.from?.id ?? message.sender?.id);
if (!chatId) {
  throw new Error('Missing Zalo chat ID');
}

return [{
  json: {
    chat_id: chatId,
    user_text: pick(message.text) ?? '',
    user_name: pick(chat.name ?? message.from?.name ?? message.sender?.name),
    event_name: pick($('Zalo Bot Trigger').first()?.json?.event_name ?? $('Zalo Bot Trigger').first()?.json?.event),
    received_at: new Date().toISOString(),
  },
}];

